import{t as e}from"./CS5lknDJ.js";var t={async createTransaction(t){return await e.post(`/transactions`,t)},async getAllTransactions(t){return await e.get(`/transactions`,{params:t})},async getTransactionById(t){return await e.get(`/transactions/${t}`)},async cancelTransaction(t){return await e.post(`/transactions/${t}/cancel`)},async getDashboardSummary(){return await e.get(`/transactions/summary`)}};export{t};